list_shipping_rates.code:
final response = await client.shippingRates.listShippingRates(
  queryParams: {
    'method': 'flat_rate',
    'handling_cost': 'with_handling',
    'sort': 'name',
    'order': 'asc',
  },
);
final result = response.map as Map;
for (final shippingRate in result['shipping_rates'] as List) {
  print('${(shippingRate as Map)['id']} ${shippingRate['name']} ${shippingRate['method']}');
}
final pagination = result['pagination'] as Map;
print('${pagination['total']} ${pagination['has_next']}');

count_shipping_rates.code:
