create_shipping_rate.code:
final response = await client.shippingRates.createShippingRate(
  {
    'shipping_rate': {
      'name': 'Flat 10',
      'method': 'flat_rate',
      'shipping_cost': {'amount': 10, 'type': 'fixed'},
      'handling_cost': {'amount': 5, 'type': 'percent'},
